// A compact account of Unicode 13.0 properties and case mappings.
// Each boundary begins a run whose properties remain alike.

pub fn named(spelling: &str) -> Option<&'static str> {
    NAMES.iter().find_map(|(name, text)| (*name == spelling).then_some(*text))
}
