pub fn mapped(letter: char, mode: usize) -> String {
    let sought = letter as u32;
    match CHANGES.binary_search_by_key(&sought, |entry| entry.0) {
        Ok(index) => CHANGES[index].1[mode].to_owned(),
        Err(_) => String::from(letter),
    }
}
