pub fn test(input: &str, verb: &str) -> Option<bool> {
    if verb == "isascii" { return Some(input.bytes().all(|b| b < 128)); }
    let mut yes = !input.is_empty() || verb == "isprintable";
    let mut case_seen = false;
    for (position, letter) in input.chars().enumerate() {
        let bits = properties(letter);
        let accepted = match verb {
            "isalpha" => bits & 1 > 0,
            "isdecimal" => bits & 2 > 0,
            "isdigit" => bits & 4 > 0,
            "isnumeric" => bits & 8 > 0,
            "isalnum" => bits & 9 > 0,
            "isspace" => bits & 16 > 0,
            "isprintable" => bits & 32 > 0,
            "isidentifier" => bits & (64 << usize::from(position > 0)) > 0,
            "islower" => { case_seen |= bits & 256 > 0; bits & 1536 == 0 },
            "isupper" => { case_seen |= bits & 512 > 0; bits & 1280 == 0 },
            _ => return None,
        };
        yes &= accepted;
    }
    if !["isalpha", "isdecimal", "isdigit", "isnumeric", "isalnum", "isspace", "isprintable", "isidentifier", "islower", "isupper"].contains(&verb) { return None; }
    Some(yes && (!matches!(verb, "islower" | "isupper") || case_seen))
}

pub fn change(input: &str, verb: &str) -> Option<String> {
    match verb {
        "lower" => Some(input.to_lowercase()),
        "upper" | "casefold" => Some(input.chars().map(|c| mapped(c, if verb == "upper" { 0 } else { 2 })).collect()),
        "title" | "capitalize" | "swapcase" => {
            let mut leading = true;
            let result = input.chars().enumerate().map(|(place, letter)| {
                let kind = properties(letter);
                let pick = if verb == "swapcase" {
                    if kind & 256 > 0 { 0 } else if kind & 512 > 0 { 1 } else { return String::from(letter); }
                } else if verb == "capitalize" && place == 0 || verb == "title" && leading { 3 } else { 1 };
                leading = kind & 1792 == 0;
                mapped(letter, pick)
            }).collect();
            Some(result)
        }
        _ => None,
    }
}

pub fn quoted(input: &str, seven_bit: bool) -> String {
    let delimiter = match (input.contains('\''), input.contains('"')) { (true, false) => '"', _ => '\'' };
    let mut pieces = vec![delimiter.to_string()];
    for letter in input.chars() {
        let number = u32::from(letter);
        let piece = if letter == delimiter || letter == '\\' { format!("\\{letter}") }
            else if let Some(short) = match letter { '\t' => Some('t'), '\n' => Some('n'), '\r' => Some('r'), _ => None } { format!("\\{short}") }
            else if properties(letter) & 32 > 0 && (!seven_bit || number < 128) { letter.to_string() }
            else { match number { 0..=255 => format!("\\x{number:02x}"), 256..=65535 => format!("\\u{number:04x}"), _ => format!("\\U{number:08x}") } };
        pieces.push(piece);
    }
    pieces.push(String::from(delimiter));
    pieces.concat()
}

pub fn tabs(input: &str, step: usize) -> String {
    let (mut written, mut place) = (String::new(), 0usize);
    input.chars().for_each(|letter| match letter {
        '\t' => {
            let end = if step > 0 { place + step - place % step } else { place };
            while place < end { written.push(' '); place += 1; }
        }
        '\r' | '\n' => { written.push(letter); place = 0; }
        _ => { written.push(letter); place += 1; }
    });
    written
}

pub fn encode(input: &str, restricted: bool, handling: usize) -> Option<Vec<u8>> {
    if !restricted { return Some(Vec::from(input.as_bytes())); }
    let fragments = input.chars().map(|letter| {
        let ordinal = u32::from(letter);
        if ordinal < 128 { return Some(letter.to_string()); }
        match handling {
            1 => Some(String::new()),
            2 => Some(String::from("?")),
            5 => Some(format!("&#{};", ordinal)),
            3 => Some(match ordinal {
                128..=255 => format!("\\x{:02x}", ordinal),
                256..=65535 => format!("\\u{:04x}", ordinal),
                _ => format!("\\U{:08x}", ordinal),
            }),
            _ => None,
        }
    }).collect::<Option<String>>()?;
    Some(fragments.into_bytes())
}

pub fn decode(input: &[u8], restricted: bool, handling: usize) -> Option<String> {
    let mut remaining = input;
    let mut result = String::new();
    while !remaining.is_empty() {
        let good;
        let count;
        if restricted {
            good = remaining.iter().take_while(|byte| **byte < 128).count(); count = 1;
        } else {
            match std::str::from_utf8(remaining) {
                Ok(whole) => { result.push_str(whole); return Some(result); }
                Err(fault) => { good = fault.valid_up_to(); count = fault.error_len().unwrap_or(remaining.len() - good); }
            }
        }
        result.push_str(std::str::from_utf8(&remaining[..good]).ok()?);
        remaining = &remaining[good..];
        if remaining.len() == 0 { break; }
        if handling == 2 { result.push('\u{fffd}'); }
        else if handling == 3 { result.extend(remaining[..count].iter().map(|number| format!("\\x{:02x}", number))); }
        else if handling != 1 { return None; }
        remaining = &remaining[count..];
    }
    Some(result)
}

pub fn quoted_points(ordinals: &[u32], limited: bool) -> String {
    let quotation = match (ordinals.contains(&0x27), ordinals.contains(&0x22)) { (true, false) => '"', _ => '\'' };
    let middle: String = ordinals.iter().map(|&number| {
        match char::from_u32(number) {
            None => format!("\\u{:04x}", number),
            Some(letter) if letter == quotation || letter == '\\' => format!("\\{}", letter),
            Some('\'' | '"') => char::from_u32(number).unwrap().to_string(),
            Some(letter) => { let escaped = quoted(&String::from(letter), limited); escaped[1..escaped.len()-1].to_owned() }
        }
    }).collect();
    format!("{}{}{}", quotation, middle, quotation)
}
